// Источник: web-тест .qa/e2e/tests/reminders/rm-02-reminders-off-manage-link.spec.ts, план .qa/e2e/specs/reminders.md, кейс .qa/tests/reminders/RM-02-system-reminders-off.md
// Тикет #6a86f7fa. Меняет настройку «תזכורות במערכת» — в конце возвращается «включено».
import { expect, driver } from '@wdio/globals';
import { byText, byLabel, byLabelStartsWith, tapLabel, expectTextContains, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
/** Минимальный тип элемента (подходит и для WebdriverIO.Element, и для ChainablePromiseElement). */
type El = {
  getAttribute(name: string): Promise<string | null>;
  isSelected(): Promise<boolean>;
  getLocation(): Promise<{ x: number; y: number }>;
  getSize(): Promise<{ width: number; height: number }>;
};

async function openProfile() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
}
async function isOn(el: El) {
  if (driver.isAndroid) return (await el.getAttribute('checked')) === 'true';
  const v = await el.getAttribute('value');
  return v === '1' || v === 'true';
}
async function reminderSwitch() {
  await scrollToText('תזכורות והתראות');
  const sw = await byLabelStartsWith('תזכורות והתראות');
  await sw.waitForDisplayed();
  return sw;
}

describe('Напоминания', () => {
  afterEach(async () => { await toHome(); });

  it('RM-02 «תזכורות והתראות» выключен → «התזכורות כבויות — אפשר להפעיל בפרופיל»; «ניהול תזכורות» ведёт к тумблеру #6a86f7fa @data', async () => {
    try {
      // 1. Профиль → «תזכורות במערכת» (исходно включён) → выключить.
      await openProfile();
      let sw = await reminderSwitch();
      expect(await isOn(sw)).toBe(true);
      await sw.click();
      await expectTextContains('תזכורות והתראות: השינוי נשמר.');
      await driver.waitUntil(async () => !(await isOn(await byLabelStartsWith('תזכורות והתראות'))), { timeoutMsg: 'тумблер не выключился' });

      // 2. Главная → «תזכורות מהירות»: сообщение о выключенных напоминаниях → «ניהול תזכורות».
      await toHome();
      await (await byText('תזכורות מהירות')).waitForDisplayed({ timeout: 20000 });
      await (await byText('התזכורות כבויות — אפשר להפעיל בפרופיל')).waitForDisplayed({ timeout: 20000 });
      await expect(byText('אין כרגע תזכורות פעילות.')).not.toBeDisplayed();
      await (await byLabel('ניהול התזכורות במסך הפרופיל')).click();
      // Переход в профиль, тумблер в зоне видимости (web: /profile?focus=reminders).
      await expect(byLabelStartsWith('תזכורות והתראות')).toBeDisplayed();
    } finally {
      // 3. Уборка: включить обратно; главная без сообщения о выключенных напоминаниях.
      await openProfile();
      const sw = await reminderSwitch();
      if (!(await isOn(sw))) {
        await sw.click();
        // Включение может вызвать системный запрос уведомлений (iOS, первый раз) — см. rm-push-permission.
        await driver.acceptAlert().catch(() => {});
        await expectTextContains('תזכורות והתראות: השינוי נשמר.');
      }
      await driver.waitUntil(async () => isOn(await byLabelStartsWith('תזכורות והתראות')), { timeoutMsg: 'тумблер не включился обратно' });
      await toHome();
      await (await byText('תזכורות מהירות')).waitForDisplayed({ timeout: 20000 });
      await expect(byText('התזכורות כבויות — אפשר להפעיל בפרופיל')).not.toBeDisplayed();
    }
  });
});
